async (page) => {
  const assert = (condition, message) => { if (!condition) throw new Error(message) }
  const results = []
  await page.goto('http://127.0.0.1:5173/question-bank?status=pending')
  await page.getByRole('heading', { name: '我的题库', exact: true }).waitFor()
  assert(await page.locator('article').count() === 4, 'pending快捷入口应只显示4道待审核题')
  results.push('status=pending筛选4道草稿')
  await page.getByRole('combobox', { name: '高阶思维标签筛选' }).press('ArrowDown')
  await page.getByRole('option', { name: 'C1 建模与多重表征', exact: true }).click()
  await page.getByText('没有符合条件的习题', { exact: true }).waitFor()
  results.push('高阶思维C1与pending筛选独立组合，空结果正确')
  await page.getByRole('button', { name: '重置筛选', exact: true }).click()
  await page.getByRole('combobox', { name: '高阶思维标签筛选' }).press('ArrowDown')
  await page.getByRole('option', { name: 'C1 建模与多重表征', exact: true }).click()
  assert(await page.locator('article').count() > 0, 'C1标签应能检出题目')
  assert((await page.locator('article').allTextContents()).every(text => text.includes('C1 建模与多重表征')), 'C1筛选结果标签不一致')
  results.push('高阶思维C1筛选命中且每张卡片标签一致')
  await page.screenshot({ path: 'E:/AAA2026学习工作/智能教育软件工程实践/code/frontend/output/playwright/question-bank-thinking-filter.png', fullPage: true })
  await page.goto('http://127.0.0.1:5173/excellent-questions')
  await page.getByRole('heading', { name: '优秀习题广场', exact: true }).waitFor()
  await page.getByRole('button', { name: '详情', exact: true }).first().click()
  const detail = page.getByRole('dialog', { name: '习题详情', exact: true })
  await detail.waitFor()
  await detail.locator('img.illustration-image').waitFor()
  await page.waitForFunction(() => { const image = document.querySelector('img.illustration-image'); return image && image.complete && image.naturalWidth > 0 })
  assert((await detail.innerText()).includes('知识点：'), '优秀习题详情缺少教学属性')
  assert((await detail.innerText()).includes('教师已确认'), '优秀习题详情缺少教师确认记录')
  assert((await detail.innerText()).includes('引用来源'), '优秀习题详情缺少引用来源')
  results.push('优秀习题详情图片正常读取、中文题型/教学属性/确认/来源齐全')
  await page.waitForFunction(() => { const dialog = document.querySelector('.el-dialog'); return dialog && getComputedStyle(dialog).opacity === '1' })
  await page.screenshot({ path: 'E:/AAA2026学习工作/智能教育软件工程实践/code/frontend/output/playwright/excellent-question-detail.png', fullPage: true, animations: 'disabled' })
  const downloading = page.waitForEvent('download')
  await detail.getByRole('button', { name: '下载习题', exact: true }).click()
  const download = await downloading
  await download.saveAs('E:/AAA2026学习工作/智能教育软件工程实践/code/frontend/output/playwright/excellent-question-export.txt')
  results.push('优秀定稿TXT下载成功')
  console.log(JSON.stringify(results))
}
